    <details v-if="settingsTab === 'diagnostics'" class="panel logs-panel" open><summary><PhTerminalWindow :size="20" />诊断日志 <span class="muted">{{ snapshot.logs.length }} 条</span></summary><div class="toolbar"><div class="search-field"><PhMagnifyingGlass :size="18" /><input v-model="logQuery" aria-label="搜索诊断日志" placeholder="搜索日志" /></div><select v-model="logLevel" class="input status-select" aria-label="日志级别"><option value="all">全部级别</option><option value="info">信息</option><option value="warn">警告</option><option value="error">错误</option></select></div><div class="log-list"><div v-for="(log, index) in logs" :key="`${log.at}-${index}`" class="log-row"><time class="muted">{{ date(log.at) }}</time><span :class="log.level === 'error' ? 'error' : log.level === 'warn' ? 'warning' : 'muted'">{{ log.level.toUpperCase() }}</span><p>{{ log.message }}</p></div><p v-if="!logs.length" class="muted">暂无匹配的日志。</p></div></details>
